  - padding : {"type": "integer", "minimum": 0, "description": "Left at each end of every candidate, in TICKS — 600000 per second, so 1 s = 600000 and one 30 fps frame = 20000. Rounded to the project's frame grid. Default 0.1 s (60000). From 0 to 9000000000000000.", "maximum": 9000000000000000}
  - threshold_db : {"maximum": 0, "description": "Quieter than this counts as silence, in dBFS in the mix. Default -40.", "type": "number"}
  - voice_confidence : {"description": "In voice mode, the Silero probability at or above which a moment counts as speech. Default 0.5. Refused outside voice mode.", "minimum": 0.1, "maximum": 0.9, "type": "number"}
  - mode : {"description": "voice (the default) judges by the cached Silero VAD probability, falling back to level over any clip whose own source window holds no voice; level is today's rule alone. voice is refused when the voice model could not be used this process — the result names it and omitting mode falls back to level with a note instead.", "type": "string", "enum": ["voice", "level"]}
